{"command":"mkdir -p /tmp/vcheck && cd /tmp/vcheck && cat > VCheck.java <<'EOF'
import org.apache.commons.text.StringSubstitutor;

public class VCheck {
    public static void main(String[] a) {
        String[] probes = {
            "${sys:tenant.name}",                          // legitimate use in tenant-config.txt
            "${url:UTF-8:file:///etc/hostname}",           // 'url' lookup -> SSRF / local file read
            "${dns:address|localhost}",                    // 'dns' lookup  -> out-of-band contact
            "${script:javascript:'PROOF-OF-RCE'}",         // 'script' lookup -> code execution
        };
        StringSubstitutor i = StringSubstitutor.createInterpolator();
        System.out.println("commons-text on classpath: "
            + StringSubstitutor.class.getProtectionDomain().getCodeSource().getLocation());
        for (String p : probes) {
            String r;
            try { r = i.replace(p); } catch (Throwable t) { r = "<threw " + t.getClass().getSimpleName() + ">"; }
            System.out.printf("  %-45s -> %s%n", p, r.equals(p) ? "<UNRESOLVED / lookup disabled>" : r.trim());
        }
    }
}
